// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

class NAryValueOperatorTest {

	@Test
	void constructorCopiesArgumentList() {
		ValueExpr first = Var.of("first");
		ValueExpr second = Var.of("second");
		List<ValueExpr> arguments = new ArrayList<>(List.of(first, second));

		Coalesce operator = new Coalesce(arguments);
		arguments.clear();

		assertThat(operator.getArguments()).containsExactly(first, second);
	}

	@Test
	void replacementSetsNewChildParent() {
		ValueExpr original = Var.of("original");
		ValueExpr replacement = Var.of("replacement");
		Coalesce operator = new Coalesce(List.of(original));

		operator.replaceChildNode(original, replacement);

		assertThat(operator.getArguments()).containsExactly(replacement);
		assertThat(replacement.getParentNode()).isSameAs(operator);
	}
}
